import java.util.stream.Collectors;

public class Solution {
    public static List<String> patchConfig(Map<String, String> base, List<String[]> patches) {
        if (patches == null || patches.isEmpty()) {
            return new ArrayList<>(base.entrySet());
        }

        List<String> result = new ArrayList<>();
        Map<String, String> current = new HashMap<>(base);

        for (String[] patch : patches) {
            if (patch == null || patch.length < 2) {
                continue; // Skip malformed patches
            }

            String operation = patch[0];
            String key = patch[1];
            String value = patch[2];

            if (operation == null || operation.isEmpty() || key == null || key.isEmpty()) {
                continue; // Reject empty key or unknown operation
            }

            if (current.containsKey(key)) {
                if ("unset".equals(operation)) {
                    current.remove(key);
                } else if ("set".equals(operation)) {
                    current.put(key, value);
                }
            } else {
                // Unknown operation
                continue;
            }
        }

        return result;
    }
}

